import requests
from pathlib import Path
import zipfile
import os
import shutil
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    """
    Downloads and extracts a zip file from a specified URL.
    Note that: the status message will contain "Error" when: Network-related exceptions are raised if the download fails. File-related exceptions are raised if there is an issue with file handling or extraction.
    The function should output with:
        tuple: A tuple containing a status message and a list of filenames in the unzipped directory, or an empty list if extraction fails.
    """
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    file_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        with open(file_path, 'wb') as f:
            f.write(response.content)
    except requests.exceptions.RequestException as e:
        return (f"Error: Network issue - {str(e)}", [])
    except Exception as e:
        return (f"Error: Download failed - {str(e)}", [])
    extract_dir = ZIP_DIR / filename.replace('.zip', '')
    if extract_dir.exists():
        shutil.rmtree(extract_dir)
    extract_dir.mkdir(parents=True, exist_ok=True)
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(extract_dir)
        files = [f for f in extract_dir.rglob('*') if f.is_file()]
        file_names = [f.name for f in files]
        return ("Download and extraction successful", file_names)
    except zipfile.BadZipFile:
        return ("Error: Bad zip file", [])
    except Exception as e:
        return (f"Error: Extraction failed - {str(e)}", [])

import requests
from pathlib import Path
import zipfile
import os
import shutil
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    """
    Downloads and extracts a zip file from a specified URL.
    Note that: the status message will contain "Error" when: Network-related exceptions are raised if the download fails. File-related exceptions are raised if there is an issue with file handling or extraction.
    The function should output with:
        tuple: A tuple containing a status message and a list of filenames in the unzipped directory, or an empty list if extraction fails.
    """
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    file_path = DOWNLOAD_DIR / filename
    extract_path = ZIP_DIR / filename.replace('.zip', '')

    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()

        with open(file_path, 'wb') as f:
            f.write(response.content)

        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(extract_path)

        files = [f.name for f in extract_path.iterdir() if f.is_file()]

        return ("Download and extraction successful", files)

    except requests.exceptions.RequestException as e:
        return (f"Error: Network-related issue - {str(e)}", [])
    except zipfile.BadZipFile:
        return ("Error: Bad zip file", [])
    except (IOError, OSError, PermissionError) as e:
        return (f"Error: File-related issue - {str(e)}", [])
    except Exception as e:
        return (f"Error: Unexpected error - {str(e)}", [])

