import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests
def task_func(myString):
    # Regular expression pattern to find URLs in the string
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+[/\w\.-]*\??[/\w\.-=&%]*'

    # Search for URLs in the input string
    url_match = re.search(url_pattern, myString)

    if not url_match:
        return "No valid URL found in the provided string."

    url = url_match.group(0)

    try:
        # Set a timeout and headers to mimic a browser request
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        }
        response = requests.get(url, headers=headers, timeout=10)
        response.raise_for_status()  # Raise an exception for bad status codes

        # Parse the HTML content
        soup = BeautifulSoup(response.content, 'html.parser')

        # Find the title tag
        title_tag = soup.find('title')

        if title_tag:
            return title_tag.get_text().strip()
        else:
            return "No title tag found in the webpage."

    except requests.exceptions.RequestException as e:
        return f"Unable to fetch the content of the URL: {url}"

